"Два щенка нашли одну косточку. Они начали ссориться, но потом разделили её поровну и вместе пообедали.": "Икки күчүк бир сөңәк тапти. Улар чекишишкә башлиди, лекин кейин уни тәң бөлүп, биргә чүшлүк қилди.",
